const runIDsForTicket = `-- name: RunIDsForTicket :many
SELECT id FROM runs WHERE ticket_id = $1 ORDER BY id
`

func (q *Queries) RunIDsForTicket(ctx context.Context, ticketID sql.NullString) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, runIDsForTicket, ticketID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const ticketActivities = `-- name: TicketActivities :many
SELECT e.ticket_id::text AS ticket_url, MAX(e.at)::timestamptz AS at,
  COALESCE((
    SELECT r.last_message FROM runs r
    WHERE r.ticket_id = e.ticket_id AND r.last_message IS NOT NULL ORDER BY r.id DESC LIMIT 1
  ), '')::text AS last_message
FROM events e
WHERE e.ticket_id IS NOT NULL
GROUP BY e.ticket_id
`

type TicketActivitiesRow struct {
	TicketUrl   string
	At          time.Time
	LastMessage string
}

func (q *Queries) TicketActivities(ctx context.Context) ([]TicketActivitiesRow, error) {
	rows, err := q.db.QueryContext(ctx, ticketActivities)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TicketActivitiesRow
	for rows.Next() {
		var i TicketActivitiesRow
		if err := rows.Scan(&i.TicketUrl, &i.At, &i.LastMessage); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const withdrawHeldIntent = `-- name: WithdrawHeldIntent :execrows
UPDATE intents SET outcome = 'withdrawn', consumed_at = $1, finished_at = $1
WHERE id = $2 AND consumed_at IS NULL AND hold_until > $1
`

type WithdrawHeldIntentParams struct {
	Now sql.NullTime
	ID  int64
}

func (q *Queries) WithdrawHeldIntent(ctx context.Context, arg WithdrawHeldIntentParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, withdrawHeldIntent, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
